namespace sv_25510741da6a4444adb780ad9b14ab46.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

using sv_25510741da6a4444adb780ad9b14ab46.Models;

namespace sv_25510741da6a4444adb780ad9b14ab46.Services;

public class ApplicationService : IApplicationService
{
    public async Task<int> SubmitApplicationAsync(JobApplication application)
    {
        await Task.Delay(1000);
        return Random.Shared.Next(10000, 99999);
    }

    public async Task<bool> ValidateEmailAsync(string email)
    {
        await Task.Delay(300);
        return !string.IsNullOrWhiteSpace(email)
            && email.Contains('@')
            && email.Contains('.');
    }
}

@namespace sv_25510741da6a4444adb780ad9b14ab46.Components.Pages.JobApplication

<nav class="step-indicator" aria-label="Application progress">
    <ol>
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step @status" @onclick="() => OnStepClick(stepIndex)" role="button" aria-current="@(stepIndex == CurrentStep ? "step" : null)">
                <span class="step-icon">
                    @if (status == "completed")
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </span>
                <span class="step-label">@StepNames[stepIndex]</span>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public IReadOnlyList<string> StepNames { get; set; } = [];
    [Parameter, EditorRequired] public IReadOnlySet<int> CompletedSteps { get; set; } = new HashSet<int>();
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private string GetStepStatus(int index)
    {
        if (index == CurrentStep) return "active";
        if (CompletedSteps.Contains(index)) return "completed";
        return "dimmed";
    }

    private async Task OnStepClick(int index)
    {
        if (CompletedSteps.Contains(index))
        {
            await OnStepSelected.InvokeAsync(index);
        }
    }
}

@namespace sv_25510741da6a4444adb780ad9b14ab46.Components.Pages.JobApplication

<fieldset class="work-entry">
    <legend>Position @(Index + 1)</legend>

    @if (ShowRemove)
    {
        <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
    }

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Model.Company" @onchange="e => Update(Model with { Company = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Model.Title" @onchange="e => Update(Model with { Title = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Model.StartDate.ToString("yyyy-MM-dd")" @onchange="e => Update(Model with { StartDate = DateTime.Parse((string?)e.Value ?? string.Empty) })" />
        </div>

        <div class="form-group">
            <label>
                <input type="checkbox" checked="@IsCurrent" @onchange="OnCurrentChanged" />
                Currently working here
            </label>
        </div>

        @if (!IsCurrent)
        {
            <div class="form-group">
                <label>End Date</label>
                <input type="date" value="@Model.EndDate?.ToString("yyyy-MM-dd")" @onchange="e => Update(Model with { EndDate = DateTime.Parse((string?)e.Value ?? string.Empty) })" />
            </div>
        }
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Model.Description" @onchange="e => Update(Model with { Description = (string?)e.Value ?? string.Empty })"></textarea>
    </div>
</fieldset>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Model { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Model.IsCurrent;

    private async Task Update(WorkEntryModel updated)
    {
        await OnChanged.InvokeAsync(updated);
    }

    private async Task OnCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool?)e.Value ?? false;
        var updated = Model with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Model.EndDate };
        await OnChanged.InvokeAsync(updated);
    }

    public class WorkEntryModel
    {
        public string Company { get; init; } = string.Empty;
        public string Title { get; init; } = string.Empty;
        public DateTime StartDate { get; init; } = DateTime.Today;
        public DateTime? EndDate { get; init; }
        public bool IsCurrent { get; init; }
        public string Description { get; init; } = string.Empty;
    }
}

