+                CoverLetter="@coverLetter"
+                OnNext="HandleCoverLetterNext"
+                OnBack="GoBack" />
+            break;
+
+        case 4:
+            <ReviewStep @ref="reviewStepRef"
+                FullName="@fullName"
+                Email="@email"
+                Phone="@phone"
+                Address="@address"
+                WorkEntries="workEntries"
+                References="references"
+                CoverLetter="@coverLetter"
+                OnBack="GoBack"
+                OnEditSection="GoToStep"
+                OnSubmit="HandleSubmit" />
+            break;
+    }
+</div>
+
+@code {
+    private int currentStep;
+    private HashSet<int> completedSteps = new();
+    private ReviewStep? reviewStepRef;
+
+    private static readonly IReadOnlyList<string> stepNames = new[]
+    {
+        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
+    };
+
+    // Step 1 data
+    private string fullName = string.Empty;
+    private string email = string.Empty;
+    private string phone = string.Empty;
+    private string address = string.Empty;
+
+    // Step 2 data
+    private List<WorkEntryForm.WorkEntryModel> workEntries = new();
+
+    // Step 3 data
+    private List<ReferenceForm.ReferenceModel> references = new();
+
+    // Step 4 data
+    private string coverLetter = string.Empty;
+
+    private void HandlePersonalNext(PersonalInfoStep.PersonalInfoResult result)
+    {
+        fullName = result.FullName;
+        email = result.Email;
+        phone = result.Phone;
+        address = result.Address;
+        completedSteps.Add(0);
+        currentStep = 1;
+    }
+
+    private void HandleWorkNext(List<WorkEntryForm.WorkEntryModel> entries)
+    {
+        workEntries = entries;
+        completedSteps.Add(1);
+        currentStep = 2;
+    }
+
+    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> refs)
+    {
+        references = refs;
+        completedSteps.Add(2);
+        currentStep = 3;
+    }
+
+    private void HandleCoverLetterNext(string letter)
+    {
+        coverLetter = letter;
+        completedSteps.Add(3);
+        currentStep = 4;
+    }
+
+    private async Task HandleSubmit()
+    {
+        try
+        {
+            var application = new JobApplication(
+                new PersonalInfo(fullName, email, phone, address),
+                new WorkHistory(workEntries.Select(e => new WorkEntry(
+                    e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
+                )).ToList()),
+                references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
+                coverLetter
+            );
+
+            var id = await ApplicationService.SubmitApplicationAsync(application);
+            reviewStepRef?.SetSubmitted(id);
+        }
+        catch (Exception ex)
+        {
+            reviewStepRef?.SetError($"Submission failed: {ex.Message}");
+        }
+    }
+
+    private void GoToStep(int step)
+    {
+        currentStep = step;
+    }
+
+    private void GoBack()
+    {
+        if (currentStep > 0)
+        {
+            currentStep--;
+        }
+    }
+}
+

